CREATE TABLE public.cursos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), nome text NOT NULL, descricao text, carga_horaria numeric, valor_mensal_padrao numeric, valor_matricula_padrao numeric, ativo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.cursos TO authenticated; GRANT ALL ON public.cursos TO service_role;
ALTER TABLE public.cursos ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner pedagogy courses" ON public.cursos FOR ALL TO authenticated USING (public.has_owner_access()) WITH CHECK (public.has_owner_access());
CREATE UNIQUE INDEX cursos_nome_unique ON public.cursos(lower(trim(nome)));
CREATE TABLE public.horarios (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), descricao text NOT NULL, dias_semana integer[] NOT NULL DEFAULT '{}', hora_inicio time, hora_fim time, ativo boolean NOT NULL DEFAULT true);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.horarios TO authenticated; GRANT ALL ON public.horarios TO service_role;
ALTER TABLE public.horarios ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner pedagogy schedules" ON public.horarios FOR ALL TO authenticated USING (public.has_owner_access()) WITH CHECK (public.has_owner_access());
CREATE TABLE public.turmas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), codigo text UNIQUE NOT NULL, curso_id uuid NOT NULL REFERENCES public.cursos(id), horario_id uuid REFERENCES public.horarios(id), data_inicio date, data_previsao_termino date, disponivel_matricula boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'em_andamento' CHECK(status IN ('em_andamento','encerrada')), observacoes text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.turmas TO authenticated; GRANT ALL ON public.turmas TO service_role;
ALTER TABLE public.turmas ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner pedagogy classes" ON public.turmas FOR ALL TO authenticated USING (public.has_owner_access()) WITH CHECK (public.has_owner_access());
CREATE TABLE public.matriculas_curso (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), aluno_id uuid NOT NULL REFERENCES public.alunos(id) ON DELETE CASCADE, ordem integer NOT NULL CHECK(ordem IN (1,2)), curso_id uuid REFERENCES public.cursos(id), turma_id uuid REFERENCES public.turmas(id), horario_id uuid REFERENCES public.horarios(id), status text NOT NULL DEFAULT 'cursando' CHECK(status IN ('cursando','concluido','formado','cancelado')), data_conclusao date, motivo_cancelamento text, valor_mensal numeric, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(aluno_id,ordem), UNIQUE(aluno_id,curso_id), UNIQUE(aluno_id,turma_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.matriculas_curso TO authenticated; GRANT ALL ON public.matriculas_curso TO service_role;
ALTER TABLE public.matriculas_curso ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner course enrollments" ON public.matriculas_curso FOR ALL TO authenticated USING (public.has_owner_access()) WITH CHECK (public.has_owner_access());
CREATE TABLE public.aluno_followups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), aluno_id uuid NOT NULL REFERENCES public.alunos(id) ON DELETE CASCADE, data date NOT NULL DEFAULT (now() AT TIME ZONE 'America/Sao_Paulo')::date, descricao text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.aluno_followups TO authenticated; GRANT ALL ON public.aluno_followups TO service_role;
ALTER TABLE public.aluno_followups ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner student followups" ON public.aluno_followups FOR ALL TO authenticated USING (public.has_owner_access()) WITH CHECK (public.has_owner_access());
CREATE INDEX aluno_followups_date ON public.aluno_followups(data DESC,aluno_id);
ALTER TABLE public.alunos ADD COLUMN foto_url text, ADD COLUMN valor_matricula numeric, ADD COLUMN data_matricula date;
INSERT INTO public.cursos(nome) SELECT DISTINCT ON (lower(trim(curso))) trim(curso) FROM public.alunos WHERE trim(curso)<>'' ORDER BY lower(trim(curso)),trim(curso);
INSERT INTO public.horarios(descricao) SELECT DISTINCT trim(horario) FROM public.alunos WHERE trim(horario)<>'';
INSERT INTO public.turmas(codigo,curso_id,horario_id,observacoes) SELECT 'LEG-'||row_number() OVER(ORDER BY a.curso,a.turma,a.horario),c.id,h.id,'Importação: turma '||a.turma FROM (SELECT DISTINCT trim(curso) curso,trim(turma) turma,trim(horario) horario FROM public.alunos WHERE trim(curso)<>'' AND trim(turma)<>'') a JOIN public.cursos c ON lower(c.nome)=lower(a.curso) LEFT JOIN public.horarios h ON h.descricao=a.horario;
INSERT INTO public.matriculas_curso(aluno_id,ordem,curso_id,turma_id,horario_id,status,data_conclusao,valor_mensal) SELECT a.id,1,c.id,t.id,h.id,CASE a.status WHEN 'Cancelado' THEN 'cancelado' WHEN 'Concluído' THEN 'concluido' ELSE 'cursando' END,CASE WHEN a."dataStatus" ~ '^\d{4}-\d{2}-\d{2}$' THEN a."dataStatus"::date ELSE NULL END,a."valorMensal" FROM public.alunos a LEFT JOIN public.cursos c ON lower(c.nome)=lower(trim(a.curso)) LEFT JOIN public.horarios h ON h.descricao=trim(a.horario) LEFT JOIN public.turmas t ON t.curso_id=c.id AND t.horario_id IS NOT DISTINCT FROM h.id AND t.observacoes='Importação: turma '||trim(a.turma);
CREATE FUNCTION public.pedagogico_validar_matricula() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE t public.turmas; novo boolean; BEGIN
novo := TG_OP='INSERT'; IF TG_OP='UPDATE' THEN novo := NEW.turma_id IS DISTINCT FROM OLD.turma_id OR NEW.curso_id IS DISTINCT FROM OLD.curso_id; END IF;
IF NEW.turma_id IS NOT NULL THEN SELECT * INTO t FROM public.turmas WHERE id=NEW.turma_id; IF t.curso_id IS DISTINCT FROM NEW.curso_id THEN RAISE EXCEPTION 'A turma não pertence ao curso.'; END IF; IF novo AND (NOT t.disponivel_matricula OR t.status<>'em_andamento') THEN RAISE EXCEPTION 'Turma não disponível para matrícula.'; END IF; NEW.horario_id:=t.horario_id; END IF;
IF NEW.status<>'cursando' AND NEW.data_conclusao IS NULL AND (TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status) THEN NEW.data_conclusao:=(now() AT TIME ZONE 'America/Sao_Paulo')::date; END IF;
IF NEW.valor_mensal<0 THEN RAISE EXCEPTION 'Mensalidade inválida.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER pedagogico_validar_matricula BEFORE INSERT OR UPDATE ON public.matriculas_curso FOR EACH ROW EXECUTE FUNCTION public.pedagogico_validar_matricula();
CREATE FUNCTION public.pedagogico_salvar_aluno(p_aluno jsonb,p_matriculas jsonb) RETURNS void LANGUAGE plpgsql SET search_path=public AS $$ DECLARE a public.alunos; m jsonb; c public.cursos; t public.turmas; h public.horarios; sid uuid; s text; BEGIN
IF NOT public.has_owner_access() THEN RAISE EXCEPTION 'Acesso negado'; END IF;
IF jsonb_array_length(p_matriculas) NOT BETWEEN 1 AND 2 THEN RAISE EXCEPTION 'Selecione um ou dois cursos.'; END IF;
sid:=(p_aluno->>'id')::uuid; SELECT * INTO a FROM public.alunos WHERE id=sid FOR UPDATE;
IF NOT FOUND THEN a:=jsonb_populate_record(NULL::public.alunos,'{"created_at": "'||now()||'"}'::text::jsonb); END IF;
a:=jsonb_populate_record(a,p_aluno); IF trim(a.nome)='' THEN RAISE EXCEPTION 'Informe o nome.'; END IF;
SELECT * INTO c FROM public.cursos WHERE id=(p_matriculas->0->>'curso_id')::uuid;
SELECT * INTO t FROM public.turmas WHERE id=(p_matriculas->0->>'turma_id')::uuid;
SELECT * INTO h FROM public.horarios WHERE id=t.horario_id;
IF c.id IS NULL AND a.curso='' THEN RAISE EXCEPTION 'Informe o curso.'; END IF;
IF c.id IS NOT NULL THEN a.curso:=c.nome; END IF;
IF t.id IS NOT NULL THEN a.turma:=CASE WHEN t.observacoes LIKE 'Importação: turma %' THEN replace(t.observacoes,'Importação: turma ','') ELSE t.codigo END; a.horario:=coalesce(h.descricao,''); END IF;
IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_matriculas) x WHERE x->>'status'='cursando') THEN a.status:='Ativo';a."dataStatus":=NULL; ELSIF EXISTS(SELECT 1 FROM jsonb_array_elements(p_matriculas) x WHERE x->>'status' IN ('concluido','formado')) THEN a.status:='Concluído'; SELECT max(x->>'data_conclusao') INTO a."dataStatus" FROM jsonb_array_elements(p_matriculas) x; ELSE a.status:='Cancelado'; SELECT max(x->>'data_conclusao') INTO a."dataStatus" FROM jsonb_array_elements(p_matriculas) x; END IF;
IF a.valor_matricula<0 OR a."valorMensal"<0 THEN RAISE EXCEPTION 'Valor inválido.'; END IF;
INSERT INTO public.alunos SELECT a.* ON CONFLICT(id) DO UPDATE SET codigo=EXCLUDED.codigo,nome=EXCLUDED.nome,responsavel=EXCLUDED.responsavel,telefone=EXCLUDED.telefone,"telefoneResponsavel"=EXCLUDED."telefoneResponsavel",cep=EXCLUDED.cep,rua=EXCLUDED.rua,numero=EXCLUDED.numero,bairro=EXCLUDED.bairro,cidade=EXCLUDED.cidade,"dataMatricula"=EXCLUDED."dataMatricula",curso=EXCLUDED.curso,turma=EXCLUDED.turma,horario=EXCLUDED.horario,status=EXCLUDED.status,"dataStatus"=EXCLUDED."dataStatus","valorMensal"=EXCLUDED."valorMensal","descontoTipo"=EXCLUDED."descontoTipo",desconto=EXCLUDED.desconto,"diaLimiteDesconto"=EXCLUDED."diaLimiteDesconto","diaVencimento"=EXCLUDED."diaVencimento","qtdMensalidades"=EXCLUDED."qtdMensalidades","primeiraCobranca"=EXCLUDED."primeiraCobranca",observacoes=EXCLUDED.observacoes,foto_url=EXCLUDED.foto_url,valor_matricula=EXCLUDED.valor_matricula,data_matricula=EXCLUDED.data_matricula;
DELETE FROM public.matriculas_curso WHERE aluno_id=sid AND ordem>jsonb_array_length(p_matriculas);
FOR m IN SELECT value FROM jsonb_array_elements(p_matriculas) LOOP
INSERT INTO public.matriculas_curso(aluno_id,ordem,curso_id,turma_id,horario_id,status,data_conclusao,motivo_cancelamento,valor_mensal) VALUES(sid,(m->>'ordem')::integer,(m->>'curso_id')::uuid,(m->>'turma_id')::uuid,(m->>'horario_id')::uuid,m->>'status',(m->>'data_conclusao')::date,m->>'motivo_cancelamento',(m->>'valor_mensal')::numeric) ON CONFLICT(aluno_id,ordem) DO UPDATE SET curso_id=EXCLUDED.curso_id,turma_id=EXCLUDED.turma_id,horario_id=EXCLUDED.horario_id,status=EXCLUDED.status,data_conclusao=EXCLUDED.data_conclusao,motivo_cancelamento=EXCLUDED.motivo_cancelamento,valor_mensal=EXCLUDED.valor_mensal;
END LOOP; END $$;
REVOKE ALL ON FUNCTION public.pedagogico_salvar_aluno(jsonb,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.pedagogico_salvar_aluno(jsonb,jsonb) TO authenticated,service_role;
CREATE POLICY "Owner student photos" ON storage.objects FOR ALL TO authenticated USING(bucket_id='fotos-alunos' AND public.has_owner_access()) WITH CHECK(bucket_id='fotos-alunos' AND public.has_owner_access());